<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php'; require_role(['admin','staff']); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 $rid=(int)($_POST['reading_id']??0);$due=$_POST['due_date']??date('Y-m-d',strtotime('+14 days'));
 $s=$pdo->prepare("SELECT r.*,c.id AS cid,c.full_name,c.account_number FROM meter_readings r JOIN customers c ON c.id=r.customer_id LEFT JOIN bills b ON b.reading_id=r.id WHERE r.id=? AND b.id IS NULL");$s->execute([$rid]);$r=$s->fetch();
 if(!$r){flash('error','Reading not found or it has already been billed.');redirect('bills.php');}
 $rate=(float)setting($pdo,'rate_per_m3','100');$amount=round((float)$r['consumption']*$rate,2);$number='WHB-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));
 $s=$pdo->prepare("INSERT INTO bills(bill_number,customer_id,reading_id,billing_period,consumption,rate_per_m3,total_amount,balance,due_date) VALUES(?,?,?,?,?,?,?,?,?)");
 $s->execute([$number,$r['cid'],$rid,$r['billing_period'],$r['consumption'],$rate,$amount,$amount,$due]);
 $u=$pdo->prepare("SELECT id FROM users WHERE customer_id=?");$u->execute([$r['cid']]);$uid=$u->fetchColumn();if($uid)add_notification($pdo,(int)$uid,"A new bill {$number} of ".money($amount)." has been generated. Due date: {$due}.");
 audit($pdo,'GENERATE BILL',$number);flash('success',"Bill {$number} generated for ".money($amount).'.');redirect('bills.php');
}
$unbilled=$pdo->query("SELECT r.id,r.billing_period,r.consumption,c.full_name,c.account_number FROM meter_readings r JOIN customers c ON c.id=r.customer_id LEFT JOIN bills b ON b.reading_id=r.id WHERE b.id IS NULL ORDER BY r.created_at DESC")->fetchAll();
$rows=$pdo->query("SELECT b.*,c.full_name,c.account_number FROM bills b JOIN customers c ON c.id=b.customer_id ORDER BY b.created_at DESC")->fetchAll();$pageTitle='Billing management';require 'includes/header.php';
?>
<div class="two-col"><div class="panel"><div class="panel-head"><h3>Generate a bill</h3></div><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Unbilled meter reading *</label><select name="reading_id" required><option value="">Select a reading</option><?php foreach($unbilled as $r):?><option value="<?=$r['id']?>"><?=e($r['account_number'].' · '.$r['full_name'].' · '.$r['billing_period'].' · '.$r['consumption'].' m³')?></option><?php endforeach;?></select><label>Payment due date</label><input type="date" name="due_date" value="<?=date('Y-m-d',strtotime('+14 days'))?>" required><button class="btn primary" <?=$unbilled?'':'disabled'?>>Generate bill</button><p class="hint">Rate: <?=money((float)setting($pdo,'rate_per_m3','100'))?> per m³. The bill uses the rate currently saved in Settings.</p></form></div><div class="panel"><h3>Billing calculation</h3><div class="formula">Consumption × Rate = Bill amount</div><p class="muted">For example, 10 m³ × KES 100 = KES 1,000. This is an illustration only. Set the correct approved tariff in Settings.</p><div class="note-box">Each meter reading can only be billed once. Bills are linked to their source reading for traceability.</div></div></div>
<div class="panel"><div class="panel-head"><h3>Generated bills</h3><input class="search-input" data-table-search="bills-table" placeholder="Search bills..."></div><div class="table-wrap"><table id="bills-table"><thead><tr><th>Bill number</th><th>Customer</th><th>Period</th><th>Usage</th><th>Amount</th><th>Balance</th><th>Due date</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['bill_number'])?></td><td><?=e($r['full_name'])?><small class="table-sub"><?=e($r['account_number'])?></small></td><td><?=e($r['billing_period'])?></td><td><?=number_format($r['consumption'],2)?> m³</td><td><?=money($r['total_amount'])?></td><td><?=money($r['balance'])?></td><td><?=e($r['due_date'])?></td><td><span class="pill <?=$r['balance']<=0?'success':'warning'?>"><?=$r['balance']<=0?'Paid':'Pending'?></span></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="8" class="empty">No bills generated.</td></tr><?php endif;?></tbody></table></div></div>
<?php require 'includes/footer.php';?>
